def link_customers(apps, schema_editor):
    """Existing one-to-one conversations with a real phone number get a directory customer (as new ones do on ingest).
    SMS behaviour does not change: the link is only read by the directory and Calls. Names saved on a phone stay per
    phone (sms.Contact); a directory name is the company's own, set by an admin."""
    Conversation = apps.get_model("sms", "Conversation")
    Customer = apps.get_model("directory", "Customer")
    CustomerDevice = apps.get_model("directory", "CustomerDevice")
    for conversation in Conversation.objects.filter(is_group=False).exclude(participants_key__contains=",").iterator(chunk_size=500):
        key = conversation.participants_key
        if not key.startswith("+"):
            continue  # short codes and sender IDs are services, not customers
        customer, _ = Customer.objects.get_or_create(key=key, defaults={"number_e164": key, "raw_sender": key})
        first, last = conversation.first_message_at or conversation.last_message_at, conversation.last_message_at
        updates = {}
        if customer.first_seen_sms is None or first < customer.first_seen_sms:
            updates["first_seen_sms"] = first
        if customer.last_seen_sms is None or last > customer.last_seen_sms:
            updates["last_seen_sms"] = last
        if updates:
            Customer.objects.filter(pk=customer.pk).update(**updates)
        link, created = CustomerDevice.objects.get_or_create(customer=customer, device_id=conversation.device_id, defaults={"first_seen": first, "last_seen": last})
        if not created:
            CustomerDevice.objects.filter(pk=link.pk).update(first_seen=min(link.first_seen, first), last_seen=max(link.last_seen, last))
        Conversation.objects.filter(pk=conversation.pk).update(customer=customer)


